    var disagreements = rows.filter(function (row) { return row.agree === false; });
    if (disagreements.length > 0) {
        lines.push('');
        lines.push('## Disagreements (' + disagreements.length + ')');
        lines.push('');
        disagreements.forEach(function (row) {
