function main(args) {
    var parsed = parseCliArgs(Array.isArray(args) ? args : []);
    if (parsed.error) {
        console.error('adaptiveCalibrationHarness: ' + parsed.error);
        console.log(USAGE);
        return 2;
    }
    if (!parsed.sample) {
        console.log(USAGE);
        return 1;
    }
    try {
        return runReplay(parsed);
    } catch (e) {
        console.error('adaptiveCalibrationHarness: could not replay ' + parsed.sample + ': ' + e);
        return 2;
    }
