diff --git a/js/common/developmentModeAdaptive.js b/js/common/developmentModeAdaptive.js
index a46f12483..a2e9645fc 100644
--- a/js/common/developmentModeAdaptive.js
+++ b/js/common/developmentModeAdaptive.js
@@ -386,14 +386,33 @@ function resolvedDevelopmentMode(customParams) {
  * keeps routed-default and shadow legs byte-identical to default-mode legs
  * even on a reused workspace. Silent on success, one honest warning on a
  * deletion failure (never fatal).
+ *
+ * Failure contract (gh-1437 review): dmtools file_delete NEVER throws — it
+ * returns {deleted:true|false} (verified by runtime probe). So the delete
+ * result is consulted, and the warning fires only when a file ACTUALLY
+ * existed and survived the call: a plain {deleted:false} on an empty
+ * workspace is the normal clean response and stays quiet. The catch is
+ * defensive only (the platform does not throw), keeping "never fatal".
  */
 function removeStaleAppendix(io) {
+    var read = (io && io.file_read) || file_read;
     var remove = (io && io.file_delete) || file_delete;
+    var path = developmentModePlan.PLAN_APPENDIX_FILE_PATH;
+    var existed = true; // unreadable probe ⇒ assume stale so a failed delete still warns
     try {
-        remove({ path: developmentModePlan.PLAN_APPENDIX_FILE_PATH });
+        existed = typeof read({ path: path }) === 'string';
     } catch (e) {
+        existed = true;
+    }
+    var result = null;
+    try {
+        result = remove({ path: path });
+    } catch (e) {
+        result = null; // defensive only — the platform does not throw
+    }
+    if (existed && !(result && result.deleted === true)) {
         console.warn('Could not remove the stale plan-mode appendix at "' +
-            developmentModePlan.PLAN_APPENDIX_FILE_PATH + '":', e);
+            path + '": ' + developmentMode.describeRawValue(result));
     }
 }

diff --git a/js/unit-tests/test_developmentModeAdaptive.js b/js/unit-tests/test_developmentModeAdaptive.js
index 99426bafc..3694252e2 100644
--- a/js/unit-tests/test_developmentModeAdaptive.js
+++ b/js/unit-tests/test_developmentModeAdaptive.js
@@ -70,7 +70,9 @@ function fsRecorder(files) {
     };
     var del = function (opts) {
         calls.deletes.push(String(opts && opts.path));
-        return true;
+        // gh-1437 rework: the real dmtools platform contract — file_delete
+        // NEVER throws, it returns {deleted:true|false} (verified by probe).
+        return { deleted: true };
     };
     return { calls: calls, file_read: read, file_write: write, file_delete: del };
 }
@@ -560,9 +562,36 @@ suite('gh-1437 UT — materializeAdaptiveAppendix (fs recorder)', function () {
             ['adaptive: would default (signals: modules=0, acceptanceBullets=0, bodyTokens=19) but shadow mode']);
     });

-    test('stale-appendix delete failure is non-fatal (warned, leg continues)', function () {
+    test('failed delete of an EXISTING stale appendix → one honest warning (real platform shape: {deleted:false}, never throws)', function () {
+        var fs = fsRecorder({});
+        fs.file_delete = function () { return { deleted: false }; };
+        // a previous leg materialized the appendix — cleanup is the routed-default
+        // leg's only defense against a stale plan appendix (docs §2.3 / AC4)
+        fs.file_read = function (opts) { return 'STALE appendix from a previous plan leg'; };
+        var captured = captureConsole(function () {
+            var r = developmentModeAdaptive.materializeAdaptiveAppendix({ developmentMode: 'adaptive' }, SMALL_TICKET_TEXT, fs);
+            assert.equal(r.ok, true, 'cleanup failure does not fail the step');
+            assert.notOk(r.error);
+        });
+        assert.equal(captured.warns.length, 1, 'one honest warning on a FAILED delete of an existing file');
+        assert.contains(captured.warns[0], APPENDIX_PATH, 'warning names the path');
+        assert.contains(captured.warns[0], 'deleted', 'warning carries the delete result, not a throw');
+    });
+
+    test('clean workspace + {deleted:false} → silent (nothing to clean is the normal response)', function () {
+        var fs = fsRecorder({});
+        fs.file_delete = function () { return { deleted: false }; };
+        var captured = captureConsole(function () {
